"use client";
import { useRef, type ComponentProps, type KeyboardEvent, type ReactNode } from "react";
import { useIndicator } from "./use-indicator";
import { useSwipeSelect } from "./use-swipe-select";
import { haptic } from "./haptics";
import { cn } from "./cn";

export interface SegmentedProps<T extends string | number> extends Omit<ComponentProps<"span">, "onChange" | "children" | "role" | "aria-label"> {
  value: T;
  /** `[value, label]` pairs, in order. */
  items: readonly (readonly [T, ReactNode])[];
  onChange: (value: T) => void;
  /** Names the group for screen readers. */
  label?: string;
}

/**
 * Single-choice control. A thumb slides between segments on a spring, arrow keys move the choice
 * (roving tabindex, like a native radio group), and it behaves as a radiogroup for assistive tech.
 */
export function Segmented<T extends string | number>({ value, items, onChange, label, className, onKeyDown, ...rest }: SegmentedProps<T>) {
  const root = useRef<HTMLSpanElement>(null);
  const { box, ready } = useIndicator(root, "[aria-checked=true]", `${String(value)}|${items.length}`);
  const choose = (v: T) => { if (v !== value) haptic("select"); onChange(v); };
  const swipe = useSwipeSelect({ index: Math.max(0, items.findIndex(([k]) => k === value)), onIndex: (i) => choose(items[i][0]), itemSelector: "button" });

  const onKey = (e: KeyboardEvent) => {
    const keys = ["ArrowRight", "ArrowDown", "ArrowLeft", "ArrowUp", "Home", "End"];
    if (!keys.includes(e.key)) return;
    e.preventDefault();
    const i = Math.max(0, items.findIndex(([k]) => k === value));
    const n = e.key === "Home" ? 0 : e.key === "End" ? items.length - 1 : (i + (e.key === "ArrowRight" || e.key === "ArrowDown" ? 1 : -1) + items.length) % items.length;
    choose(items[n][0]);
    requestAnimationFrame(() => root.current?.querySelectorAll<HTMLElement>("button")[n]?.focus());
  };

  return (
    <span ref={root} data-slot="segmented" className={cn("seg", className)} role="radiogroup" aria-label={label} {...rest} {...swipe} onKeyDown={(e) => { onKey(e); onKeyDown?.(e); }}>
      {box ? <span className={cn("seg-ind", ready && "ready")} aria-hidden="true" style={{ width: box.w, transform: `translateX(${box.x}px)` }} /> : null}
      {items.map(([k, l]) => (
        <button key={String(k)} type="button" role="radio" aria-checked={value === k} tabIndex={value === k || (!items.some(([x]) => x === value) && k === items[0][0]) ? 0 : -1} onClick={() => choose(k)}>{l}</button>
      ))}
    </span>
  );
}

/** Wrap-around group of option cards: several can be on at once (use `Segmented` for exactly one). */
export function OptionGroup({ className, ...rest }: ComponentProps<"div">) {
  return <div className={cn("opts", className)} data-slot="option-group" {...rest} />;
}

/** One toggleable card in an `OptionGroup`. `pressed` is the selected state. */
export function OptionButton({ pressed, icon, className, children, onClick, ...rest }: Omit<ComponentProps<"button">, "type"> & {
  /** Whether it is selected. */
  pressed?: boolean;
  /** A leading element, usually an `Icon`. */
  icon?: ReactNode;
}) {
  return <button type="button" data-slot="option" className={cn("opt", className)} aria-pressed={pressed} onClick={(e) => { haptic("select"); onClick?.(e); }} {...rest}>{icon}{children}</button>;
}

/* Segmented control and option buttons. Moved out of globals.css; contextual overrides (.hero .btn, .pg3 .dt) stay with the screens that need them. */
.seg{display:inline-flex;padding:3px;border-radius:99px;background:var(--tile2);gap:2px;max-width:100%}
.seg button{padding:6px 13px;border-radius:99px;font-size:0.8125rem;font-weight:600;color:var(--ink2);white-space:nowrap}
.seg button[aria-pressed=true]{background:var(--tile);color:var(--ink);box-shadow:0 1px 3px rgba(0,0,0,.14)}
.opts{display:flex;flex-wrap:wrap;gap:8px}
.opt{display:inline-flex;align-items:center;gap:8px;padding:9px 13px;border-radius:14px;background:var(--tile2);font-weight:600;font-size:0.875rem;color:var(--ink2);text-align:left}
.opt[aria-pressed=true]{background:var(--ink);color:var(--tile)}
.opt[disabled]{opacity:.55;cursor:not-allowed;text-decoration:line-through;text-decoration-color:var(--ink3)}
.seg{position:relative}
.seg button{position:relative;z-index:1}
.seg [role=radio][aria-checked=true]{color:var(--ink)}
.seg-ind{position:absolute;top:3px;bottom:3px;left:0;border-radius:99px;background:var(--tile);box-shadow:0 1px 3px rgba(0,0,0,.14);z-index:0;pointer-events:none}
.seg-ind.ready{transition:transform .5s var(--spring),width .3s var(--ease-out)}
@media (prefers-reduced-motion:reduce){
  .seg-ind.ready{transition:none}
}
.seg-full{display:flex;width:100%}
.seg-full button{flex:1;padding:12px}
/* a finger sliding across the segments chooses them: sideways is ours, vertical still scrolls (a mouse never showed this: only a real touch cancels a pan) */
.seg{touch-action:pan-y}

"use client";
import { useLayoutEffect, useState, type RefObject } from "react";

/**
 * Measures the element matching `selector` inside `root` so a single thumb can slide under the active item.
 * Re-measures when `dep` changes and whenever the root or its children resize. `ready` turns true one frame
 * after the first measurement, so the thumb appears in place instead of sliding in from the left.
 */
export function useIndicator(root: RefObject<HTMLElement | null>, selector: string, dep: unknown, childSelector = "button") {
  const [box, setBox] = useState<{ x: number; w: number } | null>(null);
  const [ready, setReady] = useState(false);
  useLayoutEffect(() => {
    const el = root.current;
    if (!el) return;
    const measure = () => {
      const on = el.querySelector<HTMLElement>(selector);
      if (on) setBox((b) => (b && b.x === on.offsetLeft && b.w === on.offsetWidth ? b : { x: on.offsetLeft, w: on.offsetWidth }));
    };
    measure();
    const ro = new ResizeObserver(measure);
    ro.observe(el);
    el.querySelectorAll(childSelector).forEach((c) => ro.observe(c));
    const raf = requestAnimationFrame(() => setReady(true));
    return () => { ro.disconnect(); cancelAnimationFrame(raf); };
  }, [root, selector, dep, childSelector]);
  return { box, ready };
}
